<script setup>
import {computed,ref,watch} from 'vue';
import {useAccess} from '../composables/access.js';
import FarmSaleForm from './FarmSaleForm.vue';
const props=defineProps({lot:Object,lots:Array,sales:Array,summary:Object}),emit=defineEmits(['changed']);
const {can}=useAccess(),form=ref(null),page=ref(1);
const money=value=>Number(value||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const number=(value,digits=3)=>Number(value||0).toLocaleString('es-ES',{maximumFractionDigits:digits});
const pages=computed(()=>Math.max(1,Math.ceil(props.sales.length/25))),visible=computed(()=>props.sales.slice((page.value-1)*25,page.value*25));
watch(pages,value=>page.value=Math.min(page.value,value));watch(()=>props.lot?.id,()=>{page.value=1;form.value=null;});
function edit(sale){if(can('accounting_write'))form.value={lot:props.lots.find(row=>row.id===sale.lot_id),sale};}
function saved(){form.value=null;emit('changed');}
function csv(){const quote=value=>{const text=String(value??'');return '"'+(/^[=+@\-\t\r]/.test(text)?"'":'')+text.replace(/"/g,'""')+'"';};const rows=[['Fecha','Lote','Cerdos','Kg por cerdo','Kg totales','Precio por kg','Importe sin IVA','Notas'],...props.sales.map(sale=>[sale.sale_date,sale.lot_code,sale.pigs,sale.kg_per_pig,sale.total_kg,sale.price_per_kg,sale.total_amount,sale.notes])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(row=>row.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='ventas-granjas.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section class="panel farm-sales"><div class="sales-heading"><div><h2>{{ lot?'Ventas del lote '+lot.code:'Ventas de la granja' }}</h2><p class="muted">Registro manual · {{ summary.count }} ventas · {{ number(summary.pigs,0) }} cerdos · {{ number(summary.total_kg) }} kg</p></div><div class="actions"><button v-if="sales.length" class="button" @click="csv">Exportar ventas CSV</button><button v-if="lot" class="button primary" :disabled="!can('accounting_write')" @click="form={lot,sale:null}">Nueva venta</button></div></div><div class="sale-summary"><div><small>Ventas sin IVA</small><strong>{{ money(summary.revenue) }}</strong></div><div><small>Gastos registrados sin IVA</small><strong>{{ money(summary.cost) }}</strong></div><div><small>Resultado registrado</small><strong :class="{negative:summary.count&&Number(summary.result)<0}">{{ summary.count?money(summary.result):'Sin ventas registradas' }}</strong></div></div><p class="muted sales-scope">Resultado = ventas manuales − gastos registrados, de todos los tipos de gasto. Respeta las fechas y el período de la vista.</p><p v-if="!lot" class="notice">Selecciona un lote de la granja para introducir una venta con su fecha, cerdos, kilos por cerdo y precio por kilo.</p><div v-if="sales.length" class="table-wrap"><table><thead><tr><th>Fecha</th><th>Lote</th><th class="number">Cerdos</th><th class="number">Kg/cerdo</th><th class="number">Kg totales</th><th class="number">Precio/kg</th><th class="number">Importe sin IVA</th></tr></thead><tbody><tr v-for="sale in visible" :key="sale.id" :class="{'sale-row':can('accounting_write')}" @click="edit(sale)"><td><button v-if="can('accounting_write')" class="sale-edit" @click.stop="edit(sale)">{{ sale.sale_date.split('-').reverse().join('/') }}</button><span v-else>{{ sale.sale_date.split('-').reverse().join('/') }}</span></td><td>{{ sale.lot_code }}</td><td class="number">{{ number(sale.pigs,0) }}</td><td class="number">{{ number(sale.kg_per_pig) }}</td><td class="number">{{ number(sale.total_kg) }}</td><td class="number">{{ number(sale.price_per_kg,5) }} €</td><td class="number">{{ money(sale.total_amount) }}</td></tr></tbody></table></div><p v-else-if="lot" class="sales-empty muted">Todavía no hay ventas registradas en este lote. Pulsa «Nueva venta» para añadir la primera.</p><div v-if="pages>1" class="actions sales-pages"><button class="button" :disabled="page===1" @click="page--">Anterior</button><span>{{ page }} / {{ pages }}</span><button class="button" :disabled="page===pages" @click="page++">Siguiente</button></div></section><FarmSaleForm v-if="form?.lot" :lot="form.lot" :sale="form.sale" @close="form=null" @saved="saved" /></template>
<style scoped>.farm-sales{padding:22px;margin:20px 0}.sales-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:20px}.farm-sales h2{font-size:1.15rem;margin:0 0 10px}.farm-sales table{width:100%}.sale-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:18px 0;border-block:1px solid #e0e6ed}.sale-summary>div{display:grid;gap:6px}.sale-summary small{color:#65748a;font-size:12px}.sale-summary strong{font-size:18px}.negative{color:#ab3a30}.sales-scope{margin:12px 0 20px}.sales-empty{padding:16px 0}.sale-row{cursor:pointer}.sale-row:hover{background:var(--primary-soft)}.number{text-align:right;white-space:nowrap}.sale-edit{background:none;border:0;color:var(--primary);padding:0;font:inherit;text-decoration:underline;cursor:pointer}.sales-pages{justify-content:center;margin-top:16px}@media(max-width:750px){.sales-heading{flex-wrap:wrap}.sale-summary{grid-template-columns:1fr}.farm-sales{padding:16px}}</style>
